<form method="post" action="<?= $base ?>/portal-demo.php?section=solicitar" class="demo-form"><input type="hidden" name="csrf" value="<?= $e($_SESSION['auth_csrf']) ?>"><input type="hidden" name="action" value="request"><input type="hidden" name="request_key" value="<?= $e($formKey) ?>"><div class="demo-honeypot" aria-hidden="true"><label>Sitio web<input name="website" tabindex="-1" autocomplete="off"></label></div><fieldset class="demo-field-group"><legend>Tu negocio</legend><div class="form-grid"><label>Tipo de negocio *<select name="sector" required><option value="">Selecciona tu actividad</option><?php foreach($sectors as $key=>$label): ?><option value="<?= $key ?>" <?= ($input['sector']??'')===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select></label><label>Ciudad<input name="city" maxlength="120" autocomplete="address-level2" value="<?= $e($input['city']??'') ?>"></label><label>Empresas *<select name="company_count"><?php foreach(['1','2','3','4','5+'] as $key): ?><option <?= ($input['company_count']??'1')===$key?'selected':'' ?>><?= $key ?></option><?php endforeach; ?></select></label><label>Usuarios *<select name="user_count"><?php foreach(['1-3','4-6','7-12','13-25','26+'] as $key): ?><option <?= ($input['user_count']??'1-3')===$key?'selected':'' ?>><?= $key ?></option><?php endforeach; ?></select></label></div></fieldset><fieldset class="demo-field-group"><legend>Tu demostración</legend><div class="form-grid"><label>Plan de interés<select name="plan_key"><option value="undecided">Ayúdame a elegir</option><?php foreach($plans as $key=>$p): ?><option value="<?= $key ?>" <?= ($input['plan_key']??$plan)===$key?'selected':'' ?>><?= $e($p['name']) ?></option><?php endforeach; ?></select></label><label>Contactarme por<select name="contact_method"><?php foreach(['whatsapp'=>'WhatsApp','phone'=>'Llamada','email'=>'Correo electrónico'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($input['contact_method']??'whatsapp')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label></div><label>¿Qué te gustaría resolver?<textarea name="requirements" maxlength="2000" rows="4"><?= $e($input['requirements']??'') ?></textarea></label></fieldset><label class="consent-label"><input type="checkbox" name="consent" value="1" required <?= ($input['consent']??'')==='1'?'checked':'' ?>><span>Autorizo que me contacten para coordinar esta demostración.</span></label><footer class="request-create-actions"><a class="site-button button-outline" href="<?= $base ?>/portal-demo.php#mis-solicitudes">Cancelar</a><button class="site-button" type="submit">Enviar solicitud</button></footer></form>
